/*View structure for view view_diagnosis_user_total */

/*!50001 DROP TABLE IF EXISTS `view_diagnosis_user_total` */;
/*!50001 DROP VIEW IF EXISTS `view_diagnosis_user_total` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`` SQL SECURITY DEFINER VIEW `view_diagnosis_user_total` AS (select `diagnosis`.`created_by` AS `user_id`,`diagnosis`.`icd_10` AS `icd_10`,count(0) AS `total` from `diagnosis` where `diagnosis`.`deleted_at` is not null group by `diagnosis`.`created_by`,`diagnosis`.`icd_10`) */;

/*View structure for view view_icd9_diagnosis_total */

/*!50001 DROP TABLE IF EXISTS `view_icd9_diagnosis_total` */;
/*!50001 DROP VIEW IF EXISTS `view_icd9_diagnosis_total` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`app`@`%` SQL SECURITY DEFINER VIEW `view_icd9_diagnosis_total` AS (select `tindakan`.`desc` AS `desc`,`diagnosis`.`icd_10` AS `icd_10`,`tindakan`.`icd_9` AS `icd_9`,count(0) AS `total` from ((`kasus` join `tindakan`) join `diagnosis`) where `tindakan`.`kasus_id` = `kasus`.`id` and `diagnosis`.`kasus_id` = `kasus`.`id` and `tindakan`.`icd_9` is not null group by `kasus`.`id`) */;

